// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Inter');

// Module-level font loading for consistent rendering on Lambda
const { fontFamily: interFamily } = loadFont();



export type TickingClockMoneyProps = Record<string, any>;

const TickingClockMoney: React.FC<TickingClockMoneyProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 10,
  clockSize = 500,
  clockFaceColor = "#ffffff",
  clockBorderColor = "#334155",
  hourHandColor = "#0f172a",
  minuteHandColor = "#475569",
  secondHandColor = "#ef4444",
  moneyColor = "#10b981",
  moneyIcon = "$",
  particleCount = 150,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser-safe background color
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation constants
  const ticksPerSecond = 1;
  const framesPerTick = fps / ticksPerSecond;
  const currentTick = Math.floor(frame / framesPerTick);
  
  // Spring for the snappy "tick" effect (pure function, frame resets every tick)
  const tickAnim = spring({ 
    frame: frame % framesPerTick, 
    fps, 
    config: { damping: 12, stiffness: 200, mass: 0.5 } 
  });

  // Entrance animations
  const clockScale = spring({ frame, fps, config: { damping: 14 } });
  const clockRotate = spring({ frame, fps, config: { damping: 12 }, from: -30, to: 0 });
  
  // Subtle pulse on every tick
  const clockPulse = interpolate(tickAnim, [0, 0.2, 1], [1, 1.03, 1]);

  // Hand Rotations
  // Second hand snaps on every tick
  const secondDegrees = (currentTick * 6) + (tickAnim * 6);
  // Minute and Hour hands move continuously at an accelerated "time-lapse" rate for visual interest
  const minuteDegrees = (frame / fps) * 60; 
  const hourDegrees = (frame / fps) * 5;

  // Generate deterministic particles synced to the clock ticks
  const particles = useMemo(() => {
    const totalTicks = durationInSeconds * ticksPerSecond;
    const particlesPerTick = Math.floor(particleCount / totalTicks);
    const arr = [];

    for (let t = 0; t < totalTicks; t++) {
      const tickFrame = t * framesPerTick;
      for (let p = 0; p < particlesPerTick; p++) {
        const i = t * particlesPerTick + p;
        arr.push({
          id: i,
          // Delay offset ensures they burst exactly when the hand ticks
          delay: tickFrame + random(`offset-${i}`) * 5,
          xOffset: (random(`x-${i}`) - 0.5) * (clockSize * 0.7),
          maxLife: fps * 1.5 + random(`life-${i}`) * fps * 2.5, // Lives between 1.5s and 4s
          scaleBase: 0.5 + random(`scale-${i}`) * 1, // 0.5x to 1.5x
          rotSpeed: (random(`rotspeed-${i}`) - 0.5) * 720,
          swayFrequency: 2 + random(`swayf-${i}`) * 3,
          swayAmplitude: 30 + random(`swaya-${i}`) * 60,
        });
      }
    }
    return arr;
  }, [particleCount, durationInSeconds, fps, clockSize]);

  // Canvas positioning
  const clockCenterY = height * 0.6;
  const clockCenterX = width * 0.5;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, transition: "none" }}>
      
      {/* Money Particles */}
      {particles.map((p) => {
        const localFrame = frame - p.delay;
        if (localFrame < 0 || localFrame > p.maxLife) return null;
        
        const progress = localFrame / p.maxLife;
        
        const startY = clockCenterY;
        const endY = -200; // Fly completely off the top of the canvas
        
        const y = interpolate(progress, [0, 1], [startY, endY]);
        const sway = Math.sin(progress * Math.PI * p.swayFrequency) * p.swayAmplitude;
        const x = clockCenterX + p.xOffset + sway;
        
        const opacity = interpolate(progress, [0, 0.1, 0.8, 1], [0, 1, 1, 0]);
        const scale = interpolate(progress, [0, 0.1, 0.9, 1], [0, p.scaleBase, p.scaleBase, 0]);
        const rotation = p.rotSpeed * progress;

        return (
          <div
            key={p.id}
            style={{
              position: "absolute",
              left: x,
              top: y,
              opacity,
              transform: `translate(-50%, -50%) scale(${scale * clockScale}) rotate(${rotation}deg)`,
              fontSize: 80,
              color: moneyColor,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              textShadow: "0px 6px 12px rgba(0,0,0,0.15)",
              transition: "none",
            }}
          >
            {moneyIcon}
          </div>
        );
      })}

      {/* Clock Container */}
      <div
        style={{
          position: "absolute",
          top: clockCenterY,
          left: clockCenterX,
          width: clockSize,
          height: clockSize,
          backgroundColor: clockFaceColor,
          borderRadius: "50%",
          border: `${clockSize * 0.04}px solid ${clockBorderColor}`,
          transform: `translate(-50%, -50%) scale(${clockScale * clockPulse}) rotate(${clockRotate}deg)`,
          boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.25)",
          transition: "none",
        }}
      >
        {/* Tick Marks */}
        {Array.from({ length: 12 }).map((_, i) => (
          <div
            key={i}
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              transform: `rotate(${i * 30}deg)`,
              transition: "none",
            }}
          >
            <div
              style={{
                position: "absolute",
                top: clockSize * 0.03,
                left: `calc(50% - ${clockSize * 0.01}px)`,
                width: clockSize * 0.02,
                height: i % 3 === 0 ? clockSize * 0.08 : clockSize * 0.04,
                backgroundColor: clockBorderColor,
                borderRadius: clockSize * 0.01,
                transition: "none",
              }}
            />
          </div>
        ))}

        {/* Hour Hand Wrapper */}
        <div style={{ position: "absolute", inset: 0, transform: `rotate(${hourDegrees}deg)`, transition: "none" }}>
          <div
            style={{
              position: "absolute",
              bottom: "50%",
              left: `calc(50% - ${clockSize * 0.02}px)`,
              width: clockSize * 0.04,
              height: "25%",
              backgroundColor: hourHandColor,
              borderRadius: clockSize * 0.02,
              transition: "none",
            }}
          />
        </div>

        {/* Minute Hand Wrapper */}
        <div style={{ position: "absolute", inset: 0, transform: `rotate(${minuteDegrees}deg)`, transition: "none" }}>
          <div
            style={{
              position: "absolute",
              bottom: "50%",
              left: `calc(50% - ${clockSize * 0.015}px)`,
              width: clockSize * 0.03,
              height: "38%",
              backgroundColor: minuteHandColor,
              borderRadius: clockSize * 0.015,
              transition: "none",
            }}
          />
        </div>

        {/* Second Hand Wrapper */}
        <div style={{ position: "absolute", inset: 0, transform: `rotate(${secondDegrees}deg)`, transition: "none" }}>
          {/* Main Pointer */}
          <div
            style={{
              position: "absolute",
              bottom: "50%",
              left: `calc(50% - ${clockSize * 0.005}px)`,
              width: clockSize * 0.01,
              height: "42%",
              backgroundColor: secondHandColor,
              borderRadius: clockSize * 0.005,
              transition: "none",
            }}
          />
          {/* Counterweight */}
          <div
            style={{
              position: "absolute",
              top: "50%",
              left: `calc(50% - ${clockSize * 0.005}px)`,
              width: clockSize * 0.01,
              height: "10%",
              backgroundColor: secondHandColor,
              borderRadius: clockSize * 0.005,
              transition: "none",
            }}
          />
        </div>

        {/* Center Pins */}
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: "50%",
            width: clockSize * 0.06,
            height: clockSize * 0.06,
            backgroundColor: hourHandColor,
            borderRadius: "50%",
            transform: "translate(-50%, -50%)",
            transition: "none",
          }}
        />
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: "50%",
            width: clockSize * 0.02,
            height: clockSize * 0.02,
            backgroundColor: secondHandColor,
            borderRadius: "50%",
            transform: "translate(-50%, -50%)",
            transition: "none",
          }}
        />
      </div>
    </AbsoluteFill>
  );
};

export default TickingClockMoney;